use std::sync::Arc;

use smallvec::SmallVec;

use crate::pattern::{Ast, ParseError, parse};
use crate::SmallString;

#[cfg(test)] use std::fmt::Write;
#[cfg(test)] use crate::pattern::is_escape_char;

pub(crate) type StateId = u16;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash, Ord, PartialOrd)]
pub(crate) enum TransitionRule {
    /// Epsilon transition
    Epsilon,
    /// Non-literal epsilon (generated by * and **)
    WildEpsilon,
    /// Edge from end of current path component to beginning of next
    NextComponent,
    /// Non-literal component ender (generated by **)
    // TODO: Maybe make is_literal a property on Transition instead of
    // duplicating rules
    WildNextComponent,
    /// Plain char
    Char(char),
    /// Matches any character (used by ?, *, **)
    Wildcard,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash, Ord, PartialOrd)]
pub(crate) struct Transition {
    pub(crate) next: StateId,
    pub(crate) rule: TransitionRule,
}

impl Transition {
    pub(crate) fn epsilon(next: StateId) -> Self {
        Self {
            next,
            rule: TransitionRule::Epsilon,
        }
    }

    pub(crate) fn wild_epsilon(next: StateId) -> Self {
        Self {
            next,
            rule: TransitionRule::WildEpsilon,
        }
    }

    pub(crate) fn chr(c: char, next: StateId) -> Self {
        Self {
            next,
            rule: TransitionRule::Char(c),
        }
    }

    pub(crate) fn next_component(next: StateId) -> Self {
        Self {
            next,
            rule: TransitionRule::NextComponent,
        }
    }

    pub(crate) fn wild_next_component(next: StateId) -> Self {
        Self {
            next,
            rule: TransitionRule::WildNextComponent,
        }
    }

    pub(crate) fn wildcard(next: StateId) -> Self {
        Self {
            next,
            rule: TransitionRule::Wildcard,
        }
    }
}

#[derive(Clone, Debug, Default)]
pub(crate) struct State {
    pub(crate) transitions: SmallVec<[Transition; 1]>,
    pub(crate) is_epsilon_frontier: bool,
    pub(crate) is_component_frontier: bool,
}

impl State {
    pub(crate) fn add_transition(&mut self, transition: Transition) {
        match transition.rule {
            TransitionRule::Char(_) | TransitionRule::Wildcard => {
                self.is_epsilon_frontier = true;
                self.is_component_frontier = true;
            }
            TransitionRule::WildEpsilon => {
                self.is_component_frontier = true;
            }
            TransitionRule::Epsilon
            | TransitionRule::NextComponent
            | TransitionRule::WildNextComponent => {}
        }
        self.transitions.push(transition);
    }

    #[cfg(test)]
    pub(crate) fn show_accepts(&self) -> String {
        let mut out = String::new();
        for t in self.transitions.iter() {
            let _ = match t.rule {
                TransitionRule::Epsilon
                | TransitionRule::WildEpsilon => write!(out, "ε"),
                TransitionRule::Char(c) if is_escape_char(c) => write!(out, "\\{c}"),
                TransitionRule::Char(c) => write!(out, "{c}"),
                TransitionRule::NextComponent
                | TransitionRule::WildNextComponent => write!(out, "{}", std::path::MAIN_SEPARATOR),
                TransitionRule::Wildcard => write!(out, "?"),
            };
        }
        out
    }
}

#[derive(Debug)]
pub(crate) struct PatternBuilder {
    pub(crate) states: Vec<State>,
}

impl PatternBuilder {
    pub(crate) fn new() -> Self {
        let states = vec![
            State::default(), // Initial
            State::default(), // Terminal
        ];
        Self {
            states,
        }
    }

    pub(crate) fn new_state(&mut self) -> StateId {
        let id = self.states.len() as StateId;
        self.states.push(State::default());
        id
    }

    pub(crate) fn connect(&mut self, from: StateId, transition: Transition) {
        self.states[from as usize].add_transition(transition);
    }
}

fn compile(sm: &mut PatternBuilder, ast: &Ast, initial: StateId, terminal: StateId) {
    match ast {
        Ast::Empty => sm.connect(initial, Transition::epsilon(terminal)),
        Ast::Char(c) => sm.connect(initial, Transition::chr(*c, terminal)),
        Ast::Wildcard => sm.connect(initial, Transition::wildcard(terminal)),
        Ast::Sep => sm.connect(initial, Transition::next_component(terminal)),
        Ast::Star => {
            let loop_state = sm.new_state();
            sm.connect(initial, Transition::wild_epsilon(loop_state));
            sm.connect(loop_state, Transition::wild_epsilon(terminal));
            sm.connect(loop_state, Transition::wildcard(loop_state));
        }
        Ast::StarStar => {
            // Branch 1: matches one or more components
            let loop_state = sm.new_state();
            sm.connect(initial, Transition::wild_epsilon(loop_state));
            sm.connect(loop_state, Transition::wild_epsilon(terminal));
            sm.connect(loop_state, Transition::wildcard(loop_state));
            sm.connect(loop_state, Transition::wild_next_component(loop_state));

            // Branch 2: matches zero components
            let skip_state = sm.new_state();
            sm.connect(initial, Transition::epsilon(skip_state));
            sm.connect(skip_state, Transition::next_component(terminal));
        }
        Ast::Sequence(nodes) => {
            assert!(!nodes.is_empty());
            let mut initial = initial;
            for (i, node) in nodes.iter().enumerate() {
                let terminal = if i + 1 == nodes.len() {
                    terminal
                } else {
                    sm.new_state()
                };
                compile(sm, node, initial, terminal);
                initial = terminal;
            }
        }
        Ast::Alternative(branches) => {
            for branch in branches {
                compile(sm, branch, initial, terminal);
            }
        }
    }
}

#[derive(Debug)]
pub struct PatternInner {
    pub(crate) base_path: SmallString,
    pub(crate) source: SmallString,
    pub(crate) states: Vec<State>,
}

impl PatternInner {
    fn compile(source: &str) -> Result<Self, ParseError> {
        let parsed = parse(source)?;
        let mut builder = PatternBuilder::new();
        compile(&mut builder, &parsed.root, 0, 1);
        Ok(Self {
            base_path: parsed.base.into(),
            source: source.into(),
            states: builder.states,
        })
    }

    pub(crate) fn source(&self) -> &str {
        &self.source
    }

    #[cfg(test)]
    fn compile_without_base(source: &str) -> Result<Self, ParseError> {
        let ast = crate::pattern::parse_ast(source)?;
        let mut builder = PatternBuilder::new();
        compile(&mut builder, &ast, 0, 1);
        Ok(Self {
            base_path: "".into(),
            source: source.into(),
            states: builder.states,
        })
    }

    #[cfg(test)]
    pub(crate) fn between(&self, from: StateId, to: StateId) -> Vec<TransitionRule> {
        self.states[from as usize].transitions.iter()
            .filter(|t| t.next == to)
            .map(|t| t.rule)
            .collect()
    }

    pub(crate) fn initial(&self) -> StateId {
        0
    }

    pub(crate) fn terminal(&self) -> StateId {
        1
    }

    pub(crate) fn get(&self, index: StateId) -> &State {
        &self.states[index as usize]
    }
}

/// A compiled glob pattern.
///
/// Pattern strings must be compiled by [`Pattern::compile`] before they can be
/// used for searching. Compiling a pattern can be expensive so don't do it in
/// a loop. However, once compiled, patterns are reference-counted and cheap to
/// clone.
///
/// See the crate documentation for in-depth syntax information.
///
/// #### Special symbols
///
/// | Symbol | Meaning |
/// | --- | --- |
/// | `*` | Matches zero or more characters, not including '/' |
/// | `**` | Matches zero or more characters, including '/' |
/// | `?` | Matches any one character |
/// | `{a,b,...}` | Matches exactly one alternative |
/// | `\` | Introduces an escape sequence |
///
/// #### Escape sequences
///
/// Possible escape sequences: `\* \? \{ \} \, \\`.
#[derive(Clone, Debug)]
pub struct Pattern {
    inner: Arc<PatternInner>,
}

impl Pattern {
    /// Compiles a pattern. Returns [`ParseError`] if the source contains a
    /// syntax error.
    pub fn compile(source: &str) -> Result<Self, ParseError> {
        Ok(Self {
            inner: Arc::new(PatternInner::compile(source)?),
        })
    }

    /// Returns the raw pattern source string.
    pub fn source(&self) -> &str {
        self.inner.source()
    }

    #[cfg(test)]
    pub(crate) fn compile_without_base(source: &str) -> Result<Self, ParseError> {
        Ok(Self {
            inner: Arc::new(PatternInner::compile_without_base(source)?),
        })
    }
}

impl std::ops::Deref for Pattern {
    type Target = PatternInner;

    fn deref(&self) -> &PatternInner {
        &self.inner
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    use TransitionRule::*;

    fn machine(s: &str) -> Pattern {
        Pattern::compile(s).unwrap()
    }

    #[test]
    fn test_compile() {
        let p = machine("");
        assert_eq!(&p.base_path[..], "");
        assert_eq!(p.between(0, 1), vec![Epsilon]);

        let p = machine("a");
        assert_eq!(&p.base_path[..], "");
        assert_eq!(p.between(0, 1), vec![Char('a')]);

        let p = machine("?");
        assert_eq!(&p.base_path[..], "");
        assert_eq!(p.between(0, 1), vec![Wildcard]);

        let p = machine("?/");
        assert_eq!(p.between(0, 2), vec![Wildcard]);
        assert_eq!(p.between(2, 1), vec![NextComponent]);

        let p = machine("*");
        assert_eq!(p.between(0, 2), vec![WildEpsilon]);
        assert_eq!(p.between(2, 2), vec![Wildcard]);
        assert_eq!(p.between(2, 1), vec![WildEpsilon]);

        let p = machine("**");
        assert_eq!(p.between(0, 2), vec![WildEpsilon]);
        assert_eq!(p.between(2, 2), vec![Wildcard, WildNextComponent]);
        assert_eq!(p.between(2, 1), vec![WildEpsilon]);
        assert_eq!(p.between(0, 3), vec![Epsilon]);
        assert_eq!(p.between(3, 1), vec![NextComponent]);

        let p = machine("a?c");
        assert_eq!(p.between(0, 2), vec![Char('a')]);
        assert_eq!(p.between(2, 3), vec![Wildcard]);
        assert_eq!(p.between(3, 1), vec![Char('c')]);

        let p = machine("{a,b}");
        assert_eq!(p.between(0, 1), vec![Char('a'), Char('b')]);

        let p = machine("{ab,cd}");
        assert_eq!(p.between(0, 2), vec![Char('a')]);
        assert_eq!(p.between(2, 1), vec![Char('b')]);
        assert_eq!(p.between(0, 3), vec![Char('c')]);
        assert_eq!(p.between(3, 1), vec![Char('d')]);
        assert_eq!(p.between(0, 1), vec![]);
    }
}
